with qa as (select e.id,e.employee_code,r.status,r.calculation_version from public.employees e join public.crew_performance_results r on r.employee_id=e.id and r.period_start=date_trunc('month',current_date)::date where e.employee_code in ('QA-CREW-CO-01','QA-CREW-IP-01','QA-CREW-NS-01','QA-CREW-NA-01','QA-CREW-IF-01'))
select jsonb_build_object('scenarios',(select count(*) from qa),'finalized',(select count(*) from qa where status='finalized'),'review_required',(select count(*) from qa where status='review_required'),'feedback',(select count(*) from public.crew_customer_feedback f where f.employee_id in(select id from qa) and f.submitted_at>=date_trunc('month',current_date)),'zero_feedback',(select count(*) from qa where not exists(select 1 from public.crew_customer_feedback f where f.employee_id=qa.id and f.submitted_at>=date_trunc('month',current_date))),'calculation_versions',(select jsonb_agg(distinct calculation_version) from qa)) as performance_qa_verification;
